import React, { useState, useEffect, useRef } from 'react';

function SeriesAIChatbot() {
  const [messages, setMessages] = useState([
    { type: 'bot', content: 'Merhaba! Size dizi önerilerinde bulunmak için buradayım. Hangi tür dizileri seviyorsunuz?' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const generateFallbackResponse = (userMessage) => {
    const lowerMessage = userMessage.toLowerCase();
    
    if (lowerMessage.includes('aksiyon') || lowerMessage.includes('macera')) {
      return 'İşte size önerebileceğim aksiyon dizileri:\n\n1. The Boys\n2. Jack Ryan\n3. The Witcher\n4. Altered Carbon\n5. The Umbrella Academy';
    } else if (lowerMessage.includes('drama') || lowerMessage.includes('duygusal')) {
      return 'İşte size önerebileceğim drama dizileri:\n\n1. This Is Us\n2. The Crown\n3. Breaking Bad\n4. Better Call Saul\n5. The Handmaid\'s Tale';
    } else if (lowerMessage.includes('komedi') || lowerMessage.includes('güldürü')) {
      return 'İşte size önerebileceğim komedi dizileri:\n\n1. The Office\n2. Brooklyn Nine-Nine\n3. Friends\n4. How I Met Your Mother\n5. The Good Place';
    } else if (lowerMessage.includes('bilim') || lowerMessage.includes('uzay')) {
      return 'İşte size önerebileceğim bilim kurgu dizileri:\n\n1. Stranger Things\n2. Black Mirror\n3. The Expanse\n4. Westworld\n5. Dark';
    } else if (lowerMessage.includes('gerilim') || lowerMessage.includes('thriller')) {
      return 'İşte size önerebileceğim gerilim dizileri:\n\n1. Mindhunter\n2. True Detective\n3. Ozark\n4. You\n5. The Sinner';
    } else {
      return 'Size daha iyi önerilerde bulunabilmem için hangi tür dizileri sevdiğinizi belirtebilir misiniz? Örneğin: aksiyon, drama, komedi, bilim kurgu veya gerilim?';
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!input.trim()) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { type: 'user', content: userMessage }]);
    setIsLoading(true);

    try {
      const response = await fetch(
        'https://api-inference.huggingface.co/models/facebook/blenderbot-400M-distill',
        {
          headers: {
            'Authorization': 'Bearer hf_xxx',
            'Content-Type': 'application/json',
          },
          method: 'POST',
          body: JSON.stringify({ inputs: userMessage }),
        }
      );

      if (!response.ok) {
        throw new Error('API yanıt vermedi');
      }

      const data = await response.json();
      const botResponse = data[0]?.generated_text || generateFallbackResponse(userMessage);
      
      setMessages(prev => [...prev, { type: 'bot', content: botResponse }]);
    } catch (error) {
      console.error('API hatası:', error);
      const fallbackResponse = generateFallbackResponse(userMessage);
      setMessages(prev => [...prev, { type: 'bot', content: fallbackResponse }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-lg overflow-hidden">
      <div className="p-4 bg-gradient-to-r from-purple-600 to-pink-600">
        <h2 className="text-xl font-bold text-white">Dizi Asistanı</h2>
      </div>
      
      <div className="h-96 overflow-y-auto p-4 space-y-4">
        {messages.map((message, index) => (
          <div
            key={index}
            className={`flex ${message.type === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div
              className={`max-w-[80%] rounded-lg p-3 ${
                message.type === 'user'
                  ? 'bg-purple-600 text-white'
                  : 'bg-gray-100 text-gray-800'
              }`}
            >
              {message.content.split('\n').map((line, i) => (
                <p key={i} className={i > 0 ? 'mt-2' : ''}>
                  {line}
                </p>
              ))}
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-gray-100 rounded-lg p-3">
              <div className="flex space-x-2">
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.4s' }}></div>
              </div>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <form onSubmit={handleSubmit} className="p-4 border-t border-gray-200">
        <div className="flex space-x-2">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Dizi önerisi isteyin..."
            className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
          />
          <button
            type="submit"
            disabled={isLoading}
            className="px-4 py-2 bg-gradient-to-r from-purple-600 to-pink-600 text-white rounded-lg hover:from-purple-700 hover:to-pink-700 transition duration-200 disabled:opacity-50"
          >
            Gönder
          </button>
        </div>
      </form>
    </div>
  );
}

export default SeriesAIChatbot;
